local function is(p1, p2) -- line: 16
    local v1, v2

    if p1 == p2 then
        if p1 ~= 0 or 1 / p1 == 1 / p2 then
            v1 = true
            v2 = true
        else
            v2 = false
        end
    else
        v2 = false
    end

    if not v2 then
        v1 = p1 ~= p1 and p2 ~= p2
    end

    return v1
end

return is
